export function albumImportPlan(catalog,saved,records){
 const cards=new Map(catalog.cards.map(c=>[c.number,c])),groups=new Map(),results=[];
 for(const record of records){const card=cards.get(record.number),result={record,number:record.number,name:card?.name||'Unread card',status:'skipped'};results.push(result);if(!card||!record.readable||!Number.isInteger(record.quantity)||record.quantity<0||record.quantity>999){result.reason=record.reason||'Card or copy count could not be confirmed.';continue}const group=groups.get(record.number)||[];group.push(result);groups.set(record.number,group)}
 const changes=[];for(const [number,group]of groups){if(new Set(group.map(r=>r.record.quantity)).size>1){for(const r of group)r.reason='Screenshots show different counts for this card. Use the newest screenshot only.';continue}const r=group[0],before=saved.get(number)||{card_number:number,quantity:0,has_foil:false,trade_foil:false},quantity=r.record.quantity;const after={...before,card_number:number,quantity,has_foil:quantity>0&&!!before.has_foil,trade_foil:quantity>1&&!!before.has_foil&&!!before.trade_foil};r.quantity=quantity;if(before.quantity===quantity&&!!before.has_foil===after.has_foil&&!!before.trade_foil===after.trade_foil){r.status='unchanged'}else{r.status='imported';changes.push({number,before:{...before},after})}for(const repeated of group.slice(1)){repeated.status='repeated';repeated.quantity=quantity}}
 return {changes,results,skipped:results.filter(r=>r.status==='skipped').length,repeated:results.filter(r=>r.status==='repeated').length,unchanged:results.filter(r=>r.status==='unchanged').length};
}
